function layers(paths: readonly string[], animated: boolean) {
  return paths.map((path, i) => (
    <path
      key={path}
      d={path}
      fill={RED}
      style={animated ? ({ "--k-layer": i } as CSSProperties) : undefined}
    />
  ));
}

interface MarkProps {
  className?: string;
  /** Texte alternatif ; décoratif par défaut (le lien autour nomme déjà Kreya). */
  title?: string;
  animated?: boolean;
}

function a11y(title?: string) {
  return title
    ? ({ role: "img", "aria-label": title } as const)
    : ({ "aria-hidden": true } as const);
}

/** Symbole seul. `small` : version 16 px (favicon, puces). */
export function BrandMark({
  className,
  title,
  animated = false,
  small = false,
}: MarkProps & { small?: boolean }) {
  if (small)
    return (
      <svg viewBox="0 0 16 16" className={className} {...a11y(title)}>
        <path d={SYMBOL_SMALL} fill={RED} />
      </svg>
    );
  return (
    <svg
      viewBox="0 0 96 88"
      className={`${animated ? "k-print " : ""}${className ?? ""}`}
      {...a11y(title)}
    >
      {layers(SYMBOL_LAYERS, animated)}
    </svg>
  );
}

/** « Kreya » seul, couleur du texte. */
export function BrandWordmark({ className, title }: MarkProps) {
  return (
    <svg viewBox="0 0 3192.43 887" className={className} {...a11y(title)}>
      <path
        fill="currentColor"
        transform="translate(-80.48 686)"
        d={WORDMARK}
      />
    </svg>
  );
}

/** Logo complet (symbole + Kreya), proportions du kit. */
export function BrandLogo({ className, title, animated = false }: MarkProps) {
  return (
    <svg
      viewBox="0 0 4607.56 1195.7"
      className={`${animated ? "k-print " : ""}${className ?? ""}`}
      {...a11y(title)}
    >
      {layers(LOGO_LAYERS, animated)}
      <path
        fill="currentColor"
        transform="translate(1334.65 994.7)"
        d={LOGO_WORD}
      />
    </svg>
  );
}
